    LIMIT 5
),
sparse_search AS(
    SELECT id, user_name, content, row_number() OVER (ORDER BY ts_rank_cd(search_vector, websearch_to_tsquery('english', 'AI framework SKU-9921')) DESC) AS rank
    FROM rag_documents
    WHERE tenant_id = '123e4567-e89b-12d3-a456-426614174000'
        AND search_vector @@ websearch_to_tsquery('english', 'AI framework SKU-9921')
    ORDER BY  search_vector @@ websearch_to_tsquery('english', 'AI framework SKU-9921') ASC
    LIMIT 5
)

SELECT 
    rd.user_name,
    rd.content,
    rd.search_vector,
    COALESCE(1.0 /(60 + ds.rank), 0.0) + COALESCE(1.0 /(60 + ss.rank), 0.0) AS rrf_score

FROM rag_documents rd  
LEFT JOIN dense_search ds ON rd.id = ds.id 
LEFT JOIN sparse_search ss ON rd.id = ss.id 
WHERE ds.id IS NOT NULL OR ss.id IS NOT NULL
ORDER BY rrf_score DESC
LIMIT 3;


-- _______________CHECKING WEITHER INDEX IS CREATED IN pg_indexes__________
SELECT 
    schemaname,
    tablename,    
    indexname, 
    indexdef 
FROM pg_indexes
WHERE tablename = 'rag_documents';